-- Migration: Year 2 - Sexual & Forensic Pathology MCQs Part 7 (236-270)
-- Date: 2026-04-24

BEGIN;

DO $$
DECLARE
    v_topic_id UUID;
BEGIN
    INSERT INTO topics (title, slug, semester_id, year_id, "order")
    VALUES ('Sexual & Forensic Pathology', 'sexual-forensic-pathology', 3, 2, 62)
    ON CONFLICT (slug) DO UPDATE SET year_id = 2, semester_id = 3
    RETURNING id INTO v_topic_id;

    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES

    -- FORENSIC: POST-MORTEM CHANGES (236-245)
    (v_topic_id, 'Algor mortis refers to the cooling of the body after death. What is the average rate of cooling in a temperate climate?', '["1 degree F per hour", "1.5 degrees F per hour for the first 12 hours", "5 degrees F per hour", "Cooling occurs instantly"]', 1, 'Algor mortis is the gradual cooling of the body until it reaches the ambient temperature. In moderate conditions, it occurs at a rate of approximately 1.5°F (0.8-1°C) per hour during the first 12 hours. It is used to estimate the time since death.'),
    (v_topic_id, 'Livor mortis (post-mortem lividity) is caused by?', '["Bacterial growth", "Gravitational settling of blood in the dependent parts of the body", "Muscle contraction", "Enzymatic digestion"]', 1, 'After the heart stops, blood settles into the lowest parts of the body due to gravity, creating a purplish-red discoloration. It starts within 30 minutes to 2 hours. "Fixation" of lividity occurs after 8-12 hours, after which it no longer shifts with body movement.'),
    (v_topic_id, 'Rigor mortis (stiffening of muscles) starts to appear first in which part of the body?', '["The legs", "Small muscles like the eyelids and jaw", "The abdomen", "The arms"]', 1, 'Rigor mortis typically follows a descending pattern (Nysten''s Law), appearing first in small muscles like the eyelids, face, and jaw, then spreading to the neck, trunk, and limbs. It is caused by the depletion of ATP, which is required for myosin to detach from actin.'),
    (v_topic_id, 'What is "Cadaveric Spasm" (instantaneous rigor)?', '["Severe muscle twitching before death", "A rare form of rigor that occurs at the moment of death, usually involving a specific group of muscles used in a final act of stress", "Stiffening that occurs after 24 hours", "Muscle relaxation after rigor"]', 1, 'Cadaveric spasm occurs instantly at death and usually involves the hand (e.g., clutching a weapon or grass). It is a vital sign indicating the person was alive and conscious at the moment of death. It cannot be imitated post-mortem.'),
    (v_topic_id, 'Putrefaction is the decomposition of organic matter by bacteria. What is the first external sign of putrefaction?', '["Skin slippage", "Greenish discoloration of the skin over the right iliac fossa (cecum)", "Foul odor", "Gas formation"]', 1, 'Putrefaction begins internally, but the first visible external sign is a greenish discoloration of the lower abdomen (over the cecum, where bacteria are most abundant). This typically appears 24-48 hours after death in temperate climates.'),
    (v_topic_id, 'Adipocere (grave wax) formation occurs in bodies that are?', '["In a dry, hot environment", "In a moist, anaerobic environment (like underwater or in damp soil)", "Exposed to direct sunlight", "Mummified"]', 1, 'Adipocere is a waxy, soap-like substance formed by the hydrogenation of body fats. It requires moisture and an anaerobic environment. It preserves the body and can help in identification and determination of injuries months later.'),
    (v_topic_id, 'Mummification occurs when a body is placed in?', '["A damp cellar", "A dry, hot environment with free circulation of air", "A sealed lead coffin", "A frozen environment"]', 1, 'Mummification is the desiccation (drying) of the body, which stops putrefaction. The skin becomes hard, brown, and leathery. It requires very dry conditions and good airflow to evaporate body fluids quickly.'),

    -- FORENSIC: MECHANICAL INJURIES (246-260)
    (v_topic_id, 'An abrasion is a superficial injury involving only the?', '["Dermis", "Epidermis", "Subcutaneous fat", "Muscle"]', 1, 'Abrasions (scratches/grazes) are the simplest form of mechanical injury. Since they involve only the epidermis, they do not leave scars. They are vital indicators of the site of impact and the direction of force.'),
    (v_topic_id, 'A contusion (bruise) is caused by the rupture of blood vessels in the?', '["Epidermis", "Dermis and subcutaneous tissue without a break in the skin surface", "Muscle only", "Bone"]', 1, 'Contusions result from blunt force trauma. The overlying skin remains intact, but bleeding occurs underneath. The age of a bruise can be estimated by its color changes: red/purple (fresh) -> blue/black -> green -> yellow -> normal.'),
    (v_topic_id, 'A laceration is a tear or split in the skin caused by blunt force. What is a key feature that distinguishes a lacerated wound from an incised wound?', '["Clean-cut edges", "Tissue bridging (nerves, vessels, and fibers crossing the gap), irregular edges, and bruising of the margins", "Presence of a foreign body", "Absence of bleeding"]', 1, 'Lacerations have irregular, torn edges with "tissue bridging" in the depths of the wound. Incised wounds (from sharp objects) have clean-cut, parallel edges and no tissue bridging.'),
    (v_topic_id, 'A "Hesitation Mark" is typically seen in which type of death?', '["Homicide", "Suicide (shallow, parallel cuts made before the final fatal wound, often on the wrists or neck)", "Accidental death", "Natural death"]', 1, 'Hesitation marks are common in suicidal incised wounds. They represent tentative, non-fatal attempts before the person gathers the courage to make the deep fatal cut.'),
    (v_topic_id, 'The depth of a "Stab Wound" is typically?', '["Less than its width", "Greater than its length or width on the skin surface", "Equal to its length", "Superficial only"]', 1, 'A stab wound is a penetrating injury caused by a long, pointed object. Its defining feature is that the depth of the track into the body is its greatest dimension.'),
    (v_topic_id, 'In a firearm injury, an "Entrance Wound" from a close-range shot (within 1-2 feet) is characterized by?', '["A large irregular hole", "Tattooing (unburnt gunpowder grains embedded in the skin) and soot deposition", "Clean edges with no marking", "Multiple small holes"]', 1, 'Close-range entrance wounds show "soot" (burning) and "tattooing" (powder stippling). If the gun is pressed against the skin (contact shot), there may be a "muzzle imprint" and a stellate (star-shaped) tear due to gas expansion.'),
    (v_topic_id, 'What is the characteristic feature of an "Exit Wound" compared to an entrance wound?', '["Soot and tattooing", "Usually larger, more irregular, and lacks an abrasion collar or soot deposition", "Always smaller", "Always circular"]', 1, 'Exit wounds are typically larger and more irregular than entrance wounds because the bullet is often deformed or tumbling. They do not show an "abrasion collar" or any evidence of burning or stippling.'),

    -- FORENSIC: ASPHYXIAL DEATHS (261-270)
    (v_topic_id, 'In a typical "Hanging" (suspension by the neck), the most common cause of death is?', '["Spinal cord fracture (hangman''s fracture)", "Cerebral ischemia due to compression of the carotid arteries and jugular veins", "Fracture of the hyoid bone", "Obstruction of the airway alone"]', 1, 'While airway obstruction can occur, death in hanging is usually due to the compression of the neck vessels, which requires much less force than compressing the airway. Death is rapid due to cerebral hypoxia.'),
    (v_topic_id, 'What is the most characteristic finding in the eyes and skin in many asphyxial deaths?', '["Jaundice", "Petechial hemorrhages (Tardieu spots) caused by increased venous pressure and capillary rupture", "Cyanosis only", "Pale skin"]', 1, 'Petechiae (tiny pinpoint hemorrhages) are frequently seen in the conjunctiva, face, and epicardium in cases of strangulation, throttling, or traumatic asphyxia.'),
    (v_topic_id, 'Manual strangulation (Throttling) is almost always?', '["Accidental", "Suicidal", "Homicidal", "A natural occurrence"]', 2, 'Throttling is the compression of the neck by human hands. It is virtually always homicidal. Characteristic findings include "crescentic" fingernail abrasions and deep bruising of the neck muscles.'),
    (v_topic_id, 'A "Fracture of the Hyoid Bone" is more common in which type of asphyxiation?', '["Hanging", "Strangulation (especially throttling in older individuals where the bone is calcified)", "Drowning", "Suffocation"]', 1, 'Because hanging often involves a knot placed high under the chin, the hyoid is often spared. In manual strangulation (throttling), direct pressure on the neck frequently fractures the hyoid bone or the thyroid cartilage.'),
    (v_topic_id, 'What is the significance of finding "Diatoms" in the bone marrow of a body found in water?', '["It proves the body was dumped after death", "It is a strong indicator of ''Wet Drowning,'' as diatoms can only reach the bone marrow if the heart was still beating to transport them from the lungs", "It indicates the body has been in water for > 1 month", "It is an accidental finding"]', 1, 'Diatoms are microscopic algae. If a person drowns while alive, they inhale water; diatoms cross the alveolar membrane into the circulation and are distributed to distant organs like the brain or bone marrow. This helps distinguish drowning from post-mortem immersion.')

    ON CONFLICT DO NOTHING;

END $$;

COMMIT;
